import type { HelpTopic } from "../../../shared/types";

export const studioHelp: HelpTopic[] = [
  { id:"agent-basics", section:"Agents", title:"What is an agent?", body:"An agent combines a model role, instructions, execution limits, and explicitly authorized tools. Agent ID is the stable API identifier; display name is the human-friendly label shown in clients." },
  { id:"agent-runtime", section:"Agents", title:"Models, steps, and instructions", body:"Model selects a configured role from models.json. Maximum tool steps limits autonomous tool calls in one request. Instructions define the agent’s responsibilities and boundaries; write specific, durable guidance." },
  { id:"agent-enabled", section:"Agents", title:"Enabled state", body:"Disabled agents remain saved but are not advertised for use. Enable an agent only after reviewing its instructions and permissions." },
  { id:"tools-utility", section:"Agents · Tools", title:"Utility tools", body:"calculate evaluates supported arithmetic. get_datetime returns the current date and time. Both are low-risk utility capabilities." },
  { id:"tools-web", section:"Agents · Tools", title:"Web access", body:"http_get fetches an allowed HTTP URL. URL safety controls still apply, but retrieved content is external and should be treated as untrusted." },
  { id:"tools-read", section:"Agents · Tools", title:"Workspace read tools", body:"workspace_list enumerates approved workspace paths, workspace_read reads a file, and workspace_search searches approved files. These tools do not intentionally modify content." },
  { id:"tools-write", section:"Agents · Tools", title:"Write and execution tools", body:"workspace_write creates or modifies approved workspace files. workspace_delete deletes workspace files. run_command executes allow-listed commands in the approved context. Grant only what the agent actually needs." },
  { id:"least-privilege", section:"Agents", title:"Safe permission defaults", body:"A general agent usually needs utilities and perhaps read-only web/workspace access. A coding agent may need workspace write and run_command, but deletion should remain off unless explicitly required. MCP assignment expands the agent with every tool exposed by that server." },
  { id:"mcp-basics", section:"MCP Servers", title:"MCP and Streamable HTTP", body:"Model Context Protocol (MCP) lets an agent use external tools and data. A Streamable HTTP server exposes MCP over an HTTPS endpoint. Connect only trusted servers and use least-privilege credentials." },
  { id:"mcp-fields", section:"MCP Servers", title:"Identity and connection fields", body:"Server ID is the stable configuration key; name is the display label. URL must be the provider’s Streamable HTTP endpoint. Start with a 30–60 second timeout and increase it only for known long-running tools." },
  { id:"mcp-auth", section:"MCP Servers", title:"Authentication and OAuth", body:"Choose None for public servers, bearer/API-key modes when provisioned by the provider, or OAuth for browser authorization. OAuth discovery locates provider metadata, Connect opens authorization, Status checks stored authorization, and Disconnect removes the local grant. Request only required scopes." },
  { id:"mcp-headers", section:"MCP Servers", title:"Headers and secrets", body:"Headers JSON is for non-secret headers only. Never paste credentials there. Configure secret header references through the project’s secure Set-McpSecret.ps1 workflow." },
  { id:"mcp-testing", section:"MCP Servers", title:"Testing and diagnostics", body:"Test Connection initializes an MCP session and reports the raw response. A successful test proves transport and authentication at that moment; saving configuration and completing OAuth are separate states." },
  { id:"status-health", section:"Status", title:"Health states", body:"Healthy means the local gateway responded and configured integrations are available. Degraded means a dependency or integration needs attention. Disconnected means the service could not be reached or authorization is absent." },
  { id:"status-fix", section:"Status", title:"MCP remediation sequence", body:"Confirm the server is enabled, save configuration, verify the URL, check OAuth Status, reconnect OAuth if needed, run Test Connection, then inspect diagnostics. If failures persist, check gateway logs and provider availability." }
];
